function spectral_radius_via_squaring(B):
    C <- B * B                      # matrix product
    for each entry (i,j) of C:
        target <- 2 if i = j else 0
        if |C[i][j] - target| > tol: fail
    return sqrt(2)

function cycle_sign_product(signs, cycle):
    p <- 1
    for t in 0..L-1:
        p <- p * signs[ edge(cycle[t], cycle[t+1 mod L]) ]
    return p

function unbalance_cycle(signs, cycle):
    if cycle_sign_product(signs, cycle) = +1:
        flip the sign of one edge of the cycle
    return signs
